export class PriceClient {
  private readonly cache = new Map<string, Promise<Price>>(); //!issue:3

  constructor(private readonly baseUrl: string) {}

  get(sku: string): Promise<Price> {
    let p = this.cache.get(sku);
    if (!p) {
      p = this.fetchPrice(sku);
      this.cache.set(sku, p); //!issue:1
    }
    return p;
  }

  private async fetchPrice(sku: string): Promise<Price> {
    const res = await fetch(`${this.baseUrl}/v1/prices/${sku}`); //!issue:4
    return (await res.json()) as Price; //!issue:2
  }
}

