type RouteStats struct {
	mu     sync.RWMutex
	counts map[string]int64
}

func (s *RouteStats) Inc(route string) {
	s.mu.RLock() //!issue:1
	s.counts[route]++ //!issue:1
	s.mu.RUnlock() //!issue:1
}

func (s *RouteStats) Snapshot() map[string]int64 {
	s.mu.RLock()
	defer s.mu.RUnlock()
	out := make(map[string]int64, len(s.counts))
	for k, v := range s.counts {
		out[k] = v
	}
	return out
}

func Middleware(stats *RouteStats, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		defer func() {
			if rec := recover(); rec != nil {
				http.Error(w, "internal error", http.StatusInternalServerError)
			}
		}()
		stats.Inc(r.URL.Path)
		next.ServeHTTP(w, r)
	})
}

