type entry struct {
	val     []byte
	expires time.Time
}

type Cache struct {
	mu      sync.Mutex
	items   map[string]entry
	onEvict func(key string)
}

func NewCache(onEvict func(string)) *Cache {
	c := &Cache{items: make(map[string]entry), onEvict: onEvict}
	go c.janitor() //!issue:1
	return c
}

func (c *Cache) janitor() {
	t := time.NewTicker(time.Minute)
	for range t.C { //!issue:1
		c.mu.Lock()
		for k, e := range c.items {
			if time.Now().After(e.expires) {
				delete(c.items, k)
				c.onEvict(k) //!issue:2
			}
		}
		c.mu.Unlock()
	}
}

func (c *Cache) Get(key string) ([]byte, bool) {
	e, ok := c.items[key] //!issue:3
	if !ok || time.Now().After(e.expires) {
		return nil, false
	}
	return e.val, true //!issue:4
}

func (c *Cache) Set(key string, val []byte, ttl time.Duration) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.items[key] = entry{val: val, expires: time.Now().Add(ttl)} //!issue:4
}
